#!/bin/bash ############################################################################# # SpotifyDL v2 — GitHub Push & Deploy Script # # Usage: GITHUB_TOKEN=ghp_xxx ./scripts/push-and-deploy.sh # ############################################################################# set -e RED='33[0;31m' GREEN='33[0;32m' BLUE='33[0;34m' YELLOW='33[1;33m' CYAN='33[0;36m' NC='33[0m' # Check token if [ -z ${GITHUB_TOKEN:-} ]; then echo -e ${RED} echo -e ${RED} echo -e ${RED} echo -e ${RED} echo -e ${NC} exit 1 fi echo -e ${CYAN} echo ╔═══════════════════════════════════════════════════════════════╗ echo ║ 🎵 SpotifyDL v2 — Push & Deploy ║ echo ╚═══════════════════════════════════════════════════════════════╝ echo -e ${NC} # Config GITHUB_USER=${GITHUB_USER:-YOUR_USERNAME} REPO_NAME=${REPO_NAME:-spotifydl-v2} APP_NAME=${FLY_APP_NAME:-spotifydl-v2} # Verify token echo -e ${BLUE}🔐 Verifying GitHub token...${NC} HTTP_CODE=$(curl -s -o /dev/null -w %{http_code} -H Authorization: token $GITHUB_TOKEN https://api.github.com/user) if [ $HTTP_CODE != 200 ]; then echo -e ${RED}❌ Invalid token or no network (HTTP $HTTP_CODE)${NC} exit 1 fi USER_CHECK=$(curl -s -H Authorization: token $GITHUB_TOKEN https://api.github.com/user | grep -o '